parameters.jsCode:
const msg = $json.message;
const lat = msg.location.latitude;
const lon = msg.location.longitude;

msg.text = `شارك المستخدم موقعه: خط العرض ${lat}, خط الطول ${lon}`;

return [{
  json: {
    ...$json,
    message: msg,
    latitude: lat,
    longitude: lon
  }
}];

const chatId = $('Telegram Trigger').first().json.message.chat.id;
let text = $json.output;

text = text.replace(/t\.me\/fortiguard_alert_bot/g, '<a href="https://t.me/fortiguard_alert_bot">t.me/fortiguard_alert_bot</a>');
text = text.replace(/@fortiguard_alert_bot/g, '<a href="https://t.me/fortiguard_alert_bot">@fortiguard_alert_bot</a>');

return [{ json: { chat_id: chatId, text: text } }];
